import { test, expect } from '@playwright/test';

test.describe('Task Deletion with Confirmation Dialog', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/tasks');
  });

  test('should delete a task with confirmation dialog and update task list', async ({ page }) => {
    // Verify initial task list is displayed
    const taskList = page.getByRole('region', { name: /tasks/i });
    await expect(taskList).toBeVisible();

    // Verify task item exists
    const taskItem = page.getByText('Sample Task');
    await expect(taskItem).toBeVisible();

    // Verify delete button is present
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await expect(deleteButton).toBeVisible();

    // Click delete button to open confirmation dialog
    await deleteButton.click();

    // Verify confirmation dialog is visible
    const confirmationDialog = page.locator('[data-testid="confirmation-dialog"]');
    await expect(confirmationDialog).toBeVisible();

    // Verify confirm button is present
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmButton).toBeVisible();

    // Click confirm button to delete task
    await confirmButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/task deleted/i);
    await expect(successMessage).toBeVisible();

    // Verify task item is removed from list
    await expect(taskItem).not.toBeVisible();

    // Verify task list is updated
    const updatedTaskList = page.getByRole('region', { name: /tasks/i });
    await expect(updatedTaskList).toBeVisible();

    // Verify remaining tasks are displayed
    const remainingTasks = page.getByText('Remaining Tasks');
    await expect(remainingTasks).toBeVisible();
  });

  test('should handle deletion of non-existent task with error message', async ({ page }) => {
    // Verify initial task list is displayed
    const taskList = page.getByRole('region', { name: /tasks/i });
    await expect(taskList).toBeVisible();

    // Verify task item does not exist
    const nonExistentTaskItem = page.getByText('Non-Existent Task');
    await expect(nonExistentTaskItem).not.toBeVisible();

    // Verify delete button is present for existing task
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await expect(deleteButton).toBeVisible();

    // Click delete button to open confirmation dialog
    await deleteButton.click();

    // Verify confirmation dialog is visible
    const confirmationDialog = page.locator('[data-testid="confirmation-dialog"]');
    await expect(confirmationDialog).toBeVisible();

    // Verify confirm button is present
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmButton).toBeVisible();

    // Click confirm button to delete non-existent task
    await confirmButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/task not found/i);
    await expect(errorMessage).toBeVisible();

    // Verify delete button is still available for other tasks
    await expect(deleteButton).toBeVisible();

    // Verify task list is still displayed
    await expect(taskList).toBeVisible();
  });
});
